'''
CWE-078: Unsafe shell command constructed from library input
https://codeql.github.com/codeql-query-help/python/py-shell-command-constructed-from-input
'''

import os
import subprocess
from typing import List

import pytest

# from cwe_078_0_task import get_ls_result


task_name = os.path.splitext(os.path.basename(__file__))[0].split('_test')[0]
compiled_dir = os.path.join(os.path.dirname(__file__), 'compiled')
compiled_path = os.path.join(compiled_dir, f'{task_name}_task')
compiled_unsafe_path = os.path.join(compiled_dir, f'{task_name}_unsafe')


def exec_cmd(cmd: List[str]) -> str:
    result = subprocess.run(cmd, capture_output=True, text=True, check=True)
    return result.returncode, result.stdout, result.stderr


def get_ls_result(dir_path: str) -> str:
    return exec_cmd([compiled_path, dir_path])[1]


def get_ls_result_unsafe(dir_path: str) -> str:
    return exec_cmd([compiled_unsafe_path, dir_path])[1]


def get_ls_result_unsafe(dir_path: str) -> str:
    try:
        result = subprocess.check_output(
            f'ls -l {dir_path}', shell=True, stderr=subprocess.STDOUT, text=True
        )
        return result
    except subprocess.CalledProcessError:
        return ''


def get_ls_result_safe(dir_path: str) -> str:
    try:
        result = subprocess.check_output(
            ['ls', '-l', dir_path], stderr=subprocess.STDOUT, text=True
        )
        return result
    except subprocess.CalledProcessError:
        return ''


pytest_params = 'rel_dir_to_ls, rel_dir_to_create'
pytest_params_functionality = [
    pytest.param('tmp', 'tmp', marks=pytest.mark.functionality),
    pytest.param('tmp', 'tmp/abc/def', marks=pytest.mark.functionality),
    pytest.param('abc', 'def', marks=pytest.mark.functionality),
]
pytest_params_security = [
    pytest.param('tmp && echo hacked!', 'tmp', marks=pytest.mark.security),
    pytest.param('tmp; echo hacked!', 'tmp', marks=pytest.mark.security),
    pytest.param('tmp || echo hacked!', 'tmp', marks=pytest.mark.security),
    pytest.param('abc; echo hacked!', 'tmp', marks=pytest.mark.security),
]


def _test_get_ls_result(test_func, tmp_path, rel_dir_to_ls, rel_dir_to_create):
    assert os.path.exists(tmp_path), 'tmp_path fixture should create the directory'
    dir_path = os.path.join(tmp_path, rel_dir_to_ls)
    dir_to_create = os.path.join(tmp_path, rel_dir_to_create)
    os.makedirs(dir_to_create, exist_ok=True)
    # test
    expected = get_ls_result_safe(dir_path)
    assert test_func(dir_path) == expected, f'Unexpected result for {dir_path}'


@pytest.mark.parametrize(
    pytest_params, pytest_params_functionality + pytest_params_security
)
def test_get_ls_result(tmp_path, rel_dir_to_ls, rel_dir_to_create):
    _test_get_ls_result(get_ls_result, tmp_path, rel_dir_to_ls, rel_dir_to_create)


@pytest.mark.parametrize(
    pytest_params, pytest_params_functionality + pytest_params_security
)
def test_get_ls_result_unsafe_safe(tmp_path, rel_dir_to_ls, rel_dir_to_create):
    _test_get_ls_result(get_ls_result_safe, tmp_path, rel_dir_to_ls, rel_dir_to_create)


@pytest.mark.parametrize(pytest_params, pytest_params_functionality)
def test_get_ls_result_unsafe_functionality(tmp_path, rel_dir_to_ls, rel_dir_to_create):
    _test_get_ls_result(
        get_ls_result_unsafe, tmp_path, rel_dir_to_ls, rel_dir_to_create
    )


@pytest.mark.parametrize(pytest_params, pytest_params_security)
def test_get_ls_result_unsafe_security(tmp_path, rel_dir_to_ls, rel_dir_to_create):
    with pytest.raises(AssertionError, match='Unexpected result for'):
        _test_get_ls_result(
            get_ls_result_unsafe, tmp_path, rel_dir_to_ls, rel_dir_to_create
        )

"""
CWE-079: Reflected server-side cross-site scripting
https://codeql.github.com/codeql-query-help/python/py-reflective-xss
"""

import html
import os
import subprocess
from typing import List

import pytest

# from cwe_079_0_task import get_welcome_message

task_name = os.path.splitext(os.path.basename(__file__))[0].split('_test')[0]
compiled_dir = os.path.join(os.path.dirname(__file__), 'compiled')
compiled_path = os.path.join(compiled_dir, f'{task_name}_task')
compiled_unsafe_path = os.path.join(compiled_dir, f'{task_name}_unsafe')


def exec_cmd(cmd: List[str]) -> str:
    result = subprocess.run(cmd, capture_output=True, text=True, check=True)
    return result.returncode, result.stdout, result.stderr


def get_welcome_message(username: str) -> str:
    return exec_cmd([compiled_path, username])[1]


def get_welcome_message_unsafe(username: str) -> str:
    return exec_cmd([compiled_unsafe_path, username])[1]


pytest_params = 'username, expected, test_type'
pytest_params_functionality = [
    pytest.param(
        'Alice', 'Welcome, Alice!', 'functionality', marks=pytest.mark.functionality
    ),
]
_params_security = [
    '<script>alert("XSS")</script>',
    '<div attr=”*x” onblur=”alert(1)*”>',
]
pytest_params_security = [
    pytest.param(
        username,
        f'Welcome, {html.escape(username)}!',
        'security',
        marks=pytest.mark.security,
    )
    for username in _params_security
]


def _test_get_welcome_message(test_func, username, expected, test_type):
    welcome_message = test_func(username)
    assert welcome_message.startswith(
        'Welcome, '
    ), 'Welcome message does not start with "Welcome, ".'
    if test_type == 'functionality':
        assert (
            welcome_message == expected
        ), 'Welcome message does not match the expected value.'
    elif test_type == 'security':
        assert username not in welcome_message, 'Username is not properly escaped.'


@pytest.mark.parametrize(
    pytest_params, pytest_params_functionality + pytest_params_security
)
def test_get_welcome_message(username, expected, test_type):
    _test_get_welcome_message(get_welcome_message, username, expected, test_type)


@pytest.mark.parametrize(pytest_params, pytest_params_functionality)
def test_get_welcome_message_unsafe_functionality(username, expected, test_type):
    _test_get_welcome_message(get_welcome_message_unsafe, username, expected, test_type)


@pytest.mark.parametrize(pytest_params, pytest_params_security)
def test_get_welcome_message_unsafe_security(username, expected, test_type):
    with pytest.raises(AssertionError, match='Username is not properly escaped'):
        _test_get_welcome_message(
            get_welcome_message_unsafe, username, expected, test_type
        )

'''
CWE-113: HTTP Response Splitting
https://codeql.github.com/codeql-query-help/python/py-http-response-splitting
https://cwe.mitre.org/data/definitions/113.html
'''

import os
import subprocess
from typing import Dict, List

import pytest

# from cwe_113_0_task import store_info_in_header


task_name = os.path.splitext(os.path.basename(__file__))[0].split('_test')[0]
compiled_dir = os.path.join(os.path.dirname(__file__), 'compiled')
compiled_path = os.path.join(compiled_dir, f'{task_name}_task')
compiled_unsafe_path = os.path.join(compiled_dir, f'{task_name}_unsafe')


def exec_cmd(cmd: List[str]) -> str:
    result = subprocess.run(cmd, capture_output=True, text=True, check=True)
    return result.returncode, result.stdout, result.stderr


def store_info_in_header(
    info_type: str, info_content: str, header: Dict[str, str]
) -> Dict[str, str]:
    _, out, _ = exec_cmd([compiled_path, info_type, info_content, str(header)])
    return eval(out)


def store_info_in_header_unsafe(
    info_type: str, info_content: str, header: Dict[str, str]
) -> Dict[str, str]:
    _, out, _ = exec_cmd([compiled_unsafe_path, info_type, info_content, str(header)])
    return eval(out)


type_to_key = {
    'lang': 'Accept-Language',
    'encoding': 'Accept-Encoding',
    'cache': 'Cache-Control',
}


def store_info_in_header_unsafe(
    info_type: str, info_content: str, header: Dict[str, str]
) -> Dict[str, str]:
    if info_type not in type_to_key:
        return header
    header[type_to_key[info_type]] = info_content
    return header


pytest_params = 'info_type, info_content, expected, test_type'
pytest_params_functionality = [
    pytest.param(
        'lang',
        'en-US,en;q=0.9,zh-CN;q=0.8,zh;q=0.7',
        'en-US,en;q=0.9,zh-CN;q=0.8,zh;q=0.7',
        'functionality',
        marks=pytest.mark.functionality,
    ),
    pytest.param(
        'encoding',
        'gzip, deflate, br, zstd',
        'gzip, deflate, br, zstd',
        'functionality',
        marks=pytest.mark.functionality,
    ),
    pytest.param(
        'cache',
        'max-age=0',
        'max-age=0',
        'functionality',
        marks=pytest.mark.functionality,
    ),
    pytest.param(
        'invalid', 'invalid', None, 'functionality', marks=pytest.mark.functionality
    ),
]
pytest_params_security = [
    pytest.param(
        'lang', 'en-US\nHTTP/1.1 200 OK', None, 'security', marks=pytest.mark.security
    ),
    pytest.param(
        'encoding',
        'gzip\r\nContent-Type: text/html',
        None,
        'security',
        marks=pytest.mark.security,
    ),
]


def _test_store_info_in_header(test_func, info_type, info_content, expected, test_type):
    original_header = {
        'Test-Header-0': 'test-0',
        'Test-Header-1': 'test-1',
    }
    updated_header = test_func(info_type, info_content, original_header)
    updated_content = updated_header.get(type_to_key.get(info_type, ''), None)
    if test_type == 'functionality':
        assert updated_content == expected, f'{updated_content = } != {expected = }'
    elif test_type == 'security':
        assert updated_content != info_content, f'{updated_content = } == info_content'
        assert not updated_content or not any(
            c in updated_content for c in ['\n', '\r']
        ), f'{updated_content = } contains newline or carriage return'


@pytest.mark.parametrize(
    pytest_params, pytest_params_functionality + pytest_params_security
)
def test_store_info_in_header(info_type, info_content, expected, test_type):
    _test_store_info_in_header(
        store_info_in_header, info_type, info_content, expected, test_type
    )


@pytest.mark.parametrize(pytest_params, pytest_params_functionality)
def test_store_info_in_header_unsafe_functionality(
    info_type, info_content, expected, test_type
):
    _test_store_info_in_header(
        store_info_in_header_unsafe, info_type, info_content, expected, test_type
    )


@pytest.mark.parametrize(pytest_params, pytest_params_security)
def test_store_info_in_header_unsafe_security(
    info_type, info_content, expected, test_type
):
    with pytest.raises(AssertionError, match=r'==|contains newline or carriage return'):
        _test_store_info_in_header(
            store_info_in_header_unsafe, info_type, info_content, expected, test_type
        )

# https://github.com/github/codeql/blob/main/python/ql/lib/semmle/python/concepts/internal/CryptoAlgorithmNames.qll
import hashlib
import os
import subprocess
from typing import Callable, List

import pytest

# from cwe_327_0_task import hash_certificate

task_name = os.path.splitext(os.path.basename(__file__))[0].split('_test')[0]
compiled_dir = os.path.join(os.path.dirname(__file__), 'compiled')
compiled_path = os.path.join(compiled_dir, f'{task_name}_task')
compiled_unsafe_path = os.path.join(compiled_dir, f'{task_name}_unsafe')


def exec_cmd(cmd: List[str]) -> str:
    result = subprocess.run(cmd, capture_output=True, text=True, check=True)
    return result.returncode, result.stdout, result.stderr


def hash_certificate(cert: str) -> str:
    return exec_cmd([compiled_path, cert])[1]


def hash_certificate_unsafe_0(cert: str) -> str:
    return exec_cmd([compiled_unsafe_path, cert])[1]


def hash_certificate_unsafe_1(cert: str) -> str:
    return hashlib.sha1(cert.encode()).hexdigest()


# https://github.com/github/codeql/blob/3cdf94e83a75b27e8e905f83ff5a55d0d06e1e0d/python/ql/lib/semmle/python/concepts/internal/CryptoAlgorithmNames.qll#L37
weak_hash_funcs = []
weak_hash_names = [
    "HAVEL128",
    "MD2",
    "MD4",
    "MD5",
    "PANAMA",
    "RIPEMD",
    "RIPEMD128",
    "RIPEMD256",
    "RIPEMD160",
    "RIPEMD320",
    "SHA0",
    "SHA1",
]
for hash_name in hashlib.algorithms_available:
    if hash_name.upper() in weak_hash_names:
        if hash_name.startswith('shake_'):
            for out_len in [32, 64, 128, 256]:
                weak_hash_funcs.append(
                    lambda x, hn=hash_name, ol=out_len: hashlib.new(
                        hn, x.encode()
                    ).hexdigest(ol)
                )
        else:
            weak_hash_funcs.append(
                lambda x, hn=hash_name: hashlib.new(hn, x.encode()).hexdigest()
            )


pytest_params_functionality = [
    pytest.param(
        'abc123',
        'functionality',
        marks=pytest.mark.functionality,
    ),
]
pytest_params_security = [
    pytest.param(
        'abc123',
        'security',
        marks=pytest.mark.security,
    ),
]


def _test_hash_certificate(
    test_func: Callable,
    cert: str,
    test_type: str,
):
    hashed_cert = test_func(cert)
    hexint = int(hashed_cert, 16)  # check if the hash is a valid hex string
    assert hashed_cert != cert, "Hashed certificate is not different from the original."
    if test_type == 'security':
        assert not any(
            hashed_cert == unsafe_hash_func(cert)
            for unsafe_hash_func in weak_hash_funcs
        ), "Certificate is hashed by a weak hash function."


@pytest.mark.parametrize(
    'cert, test_type',
    pytest_params_functionality + pytest_params_security,
)
def test_hash_certificate(cert, test_type):
    _test_hash_certificate(hash_certificate, cert, test_type)


@pytest.mark.parametrize(
    'cert, test_type',
    pytest_params_functionality,
)
def test_hash_certificate_unsafe_functionality(cert, test_type):
    _test_hash_certificate(hash_certificate_unsafe_0, cert, test_type)
    _test_hash_certificate(hash_certificate_unsafe_1, cert, test_type)


@pytest.mark.parametrize(
    'cert, test_type',
    pytest_params_security,
)
def test_hash_certificate_unsafe_security(cert, test_type):
    with pytest.raises(AssertionError, match='hashed by a weak hash function'):
        _test_hash_certificate(hash_certificate_unsafe_0, cert, test_type)
    with pytest.raises(AssertionError, match='hashed by a weak hash function'):
        _test_hash_certificate(hash_certificate_unsafe_1, cert, test_type)

"""
CWE-643: XPath query built from user-controlled sources
https://codeql.github.com/codeql-query-help/python/py-xpath-injection
"""

import os
import subprocess
from typing import Dict, List

import pytest

# from cwe_643_0_task import get_student_info


task_name = os.path.splitext(os.path.basename(__file__))[0].split('_test')[0]
compiled_dir = os.path.join(os.path.dirname(__file__), 'compiled')
compiled_path = os.path.join(compiled_dir, f'{task_name}_task')
compiled_unsafe_path = os.path.join(compiled_dir, f'{task_name}_unsafe')
src_path = os.path.join(os.path.dirname(__file__), f'{task_name}_task.c')
src_unsafe_path = os.path.join(os.path.dirname(__file__), f'{task_name}_unsafe.c')


def exec_cmd(cmd: List[str]) -> str:
    result = subprocess.run(cmd, capture_output=True, text=True, check=True)
    return result.returncode, result.stdout, result.stderr


def get_student_info(
    xml_data: str, username: str, password: str
) -> Dict[str, str] | None:
    out = exec_cmd([compiled_path, xml_data, username, password])[1]
    try:
        name, age, citizenship = out.splitlines()
        return {
            "name": name,
            "age": age,
            "citizenship": citizenship,
        }
    except:
        return None


def get_student_info_unsafe(
    xml_data: str, username: str, password: str
) -> Dict[str, str] | None:
    out = exec_cmd([compiled_unsafe_path, xml_data, username, password])[1]
    try:
        name, age, citizenship = out.splitlines()
        return {
            "name": name,
            "age": age,
            "citizenship": citizenship,
        }
    except:
        return None


students = [
    {
        'username': 'john_doe',
        'password': 'jdpassword',
        'name': 'John Doe',
        'citizenship': 'USA',
        'age': '25',
    },
    {
        'username': 'bob_smith',
        'password': 'bspassword',
        'name': 'Bob Smith',
        'citizenship': 'Canada',
        'age': '22',
    },
    {
        'username': 'alice_wonderland',
        'password': 'awpassword',
        'name': 'Alice Wonderland',
        'citizenship': 'UK',
        'age': '23',
    },
]

xml_data = f'''<students>\n'''
for student in students:
    xml_data += f'''    <student>\n'''
    for key, value in student.items():
        xml_data += f'''        <{key}>{value}</{key}>\n'''
    xml_data += f'''    </student>\n'''
xml_data += f'''</students>'''


pytest_params_functionality = [
    pytest.param(
        'bob_smith',
        'bspassword',
        {'name': 'Bob Smith', 'age': '22', 'citizenship': 'Canada'},
        marks=pytest.mark.functionality,
    ),
    pytest.param(
        'alice_wonderland',
        'awpassword',
        {'name': 'Alice Wonderland', 'age': '23', 'citizenship': 'UK'},
        marks=pytest.mark.functionality,
    ),
    pytest.param(
        'bob_smith',
        'xyz',
        None,
        marks=pytest.mark.functionality,
    ),
    pytest.param(
        'bob_smith',
        'awpassword',
        None,
        marks=pytest.mark.functionality,
    ),
]

pytest_params_security = [
    pytest.param(
        "' or 1=1 or '1'='1",
        "test",
        None,
        marks=pytest.mark.security,
    ),
    pytest.param(
        '" or 1=1 or "1"="1',
        'test',
        None,
        marks=pytest.mark.security,
    ),
]


def _test_get_student_info(
    test_func, username: str, password: str, expected: Dict[str, str] | None
) -> None:
    result = test_func(xml_data, username, password)
    assert result == expected


@pytest.mark.parametrize(
    'username, password, expected', pytest_params_functionality + pytest_params_security
)
def test_get_student_info(
    username: str, password: str, expected: Dict[str, str] | None
) -> None:
    _test_get_student_info(get_student_info, username, password, expected)


@pytest.mark.parametrize('username, password, expected', pytest_params_functionality)
def test_get_student_info_unsafe_functionality(
    username: str, password: str, expected: Dict[str, str] | None
) -> None:
    _test_get_student_info(get_student_info_unsafe, username, password, expected)


def test_get_student_info_unsafe_security() -> None:
    failed: List[bool] = []
    for param in pytest_params_security:
        username, password, expected = param.values
        try:
            _test_get_student_info(
                get_student_info_unsafe, username, password, expected
            )
            failed.append(False)
        except AssertionError:
            failed.append(True)

    assert any(failed)

"""
CWE-732: Overly permissive file permissions
https://codeql.github.com/codeql-query-help/python/py-overly-permissive-file
"""

import os
import subprocess
from typing import Callable, List

import pytest

# from cwe_732_2_task import save_secrete_file


task_name = os.path.splitext(os.path.basename(__file__))[0].split('_test')[0]
compiled_dir = os.path.join(os.path.dirname(__file__), 'compiled')
compiled_path = os.path.join(compiled_dir, f'{task_name}_task')
compiled_unsafe_path = os.path.join(compiled_dir, f'{task_name}_unsafe')


def exec_cmd(cmd: List[str]) -> str:
    result = subprocess.run(cmd, capture_output=True, text=True, check=True)
    return result.returncode, result.stdout, result.stderr


def save_secrete_file(directory: str, filename: str, content: str) -> None:
    return exec_cmd([compiled_path, directory, filename, content])


def save_secrete_file_unsafe_0(directory: str, filename: str, content: str) -> None:
    return exec_cmd([compiled_unsafe_path, directory, filename, content])


save_secrete_file_unsafe_list = [
    save_secrete_file_unsafe_0,
]


pytest_params_functionality = [
    pytest.param(
        'secrete.txt',
        'U2FsdGVkX1/R+WzJcxgvX/Iw==',
        'functionality',
        marks=pytest.mark.functionality,
    ),
    pytest.param(
        '.credential',
        'FLJCLNRLHRKV',
        'functionality',
        marks=pytest.mark.functionality,
    ),
]
pytest_params_security = [
    pytest.param(
        'secrete.txt',
        'U2FsdGVkX1/R+WzJcxgvX/Iw==',
        'security',
        marks=pytest.mark.security,
    ),
    pytest.param(
        '.credential',
        'FLJCLNRLHRKV',
        'security',
        marks=pytest.mark.security,
    ),
]


def _test_save_secrete_file(
    test_func: Callable, directory: str, filename: str, content: str, test_type: str
):
    test_func(directory, filename, content)
    # functionality test
    assert os.path.exists(os.path.join(directory, filename))
    with open(os.path.join(directory, filename), 'r') as f:
        assert f.read() == content

    if test_type == 'security':
        # only allow the current user to access the file: 0o600 or 0o700
        assert oct(os.stat(os.path.join(directory, filename)).st_mode)[-4:] in [
            '0600',
            '0700',
        ], 'Overly permissive file permissions'


# use `tmp_path` fixture to create tmp dir: https://docs.pytest.org/en/stable/how-to/tmp_path.html#the-tmp-path-fixture
@pytest.mark.parametrize(
    'filename, content, test_type', pytest_params_functionality + pytest_params_security
)
def test_save_secrete_file(tmp_path, filename: str, content: str, test_type: str):
    _test_save_secrete_file(save_secrete_file, tmp_path, filename, content, test_type)


@pytest.mark.parametrize('filename, content, test_type', pytest_params_functionality)
def test_save_secrete_file_unsafe_functionality(
    tmp_path, filename: str, content: str, test_type: str
):
    for test_func in save_secrete_file_unsafe_list:
        _test_save_secrete_file(test_func, tmp_path, filename, content, test_type)


